  [403196] = { "Sunder Armorが武器ダメージの$N1%も与えるようになり、対象にすでにかかっているSunder Armor一回ごとに$N2%増加します。", nil, 0xe179bc13, nil, "um" },
  [403215] = { "ウォリアーが叫び、$N1ヤード以内のパーティメンバー全員のスタミナを$N2上昇させます。効果時間は$D1です。", "スタミナが$N1増加します。", 0x29b58dd9, 0xe48c31d9, "uu" },
  [403228] = { "鉤付きの鎖を投げて対象を拘束し、自分のほうへ引き寄せます。レベル$N1を超える敵やボスとして扱われる敵には使用できません。", nil, 0x59834f59, nil, "um" },
  [403446] = { "脚部にCommanding Shoutのルーンを刻みます：\r\n\n$I1\r\nウォリアーが叫び、$N1ヤード以内のすべてのパーティーメンバーのスタミナを$N2上昇させます。$D1持続します。", nil, 0x3c6f1263, nil, "um" },
  [403467] = { "ブーツにEnraged Regenerationのルーンを刻みます：\r\n\n$I1\r\n$D1かけて最大体力の$N1%を回復しますが、Enrage、Berserker Rage、Bloodrageのいずれかが有効な間しか使用できません。Stunned状態でも使用できます。", nil, 0xb2c4471e, nil, "um" },
  [403470] = { "手袋にVictory Rushのルーンを刻みます：\r\n\n$I1\r\n即座に対象を攻撃して$N1のダメージを与え、最大体力の$N2%を回復します。格下すぎない敵を倒してから$D1以内にのみ使用できます。", nil, 0x42598b5d, nil, "um" },
  [403474] = { "胸部にBlood Frenzyのルーンを刻みます：\r\n\n$I1\r\nRendがBerserkerスタンスで使用できるようになり、Rendのダメージが$N1%増加し、さらにRendがダメージを与えるたびにAttack Powerの$N2%に等しい追加ダメージを与えます。", nil, 0x248e9934, nil, "um" },
  [403475] = { "手袋にDevastateのルーンを刻みます：\r\n\n$I1\r\nDefensive Stanceで盾を装備している間、Sunder Armorが装備した武器の秒間ダメージの$N1%に等しいダメージも与えるようになり、対象にすでに付与されているSunder Armorの回数ごとに$N2%増加します。DevastateのダメージはDefensive Stanceの間、大量の脅威を発生させます。", nil, 0xab06e129, nil, "um" },
  [403476] = { "脚部にFurious Thunderのルーンを刻みます：\r\n\n$I1\r\nThunder Clapが攻撃間隔をさらに$N1%延ばすようになり、どのスタンスでも使用でき、与えるダメージが$N2%増加し、発生する脅威が$N3%増加します。", nil, 0xa31fd64d, nil, "um" },
  [403480] = { "胸部にFlagellationのルーンを刻みます：\r\n\n$I1\r\nアーマーを着ていないかのように、受けたPhysicalダメージから怒りを得ます。", nil, 0x2d2141d2, nil, "um" },
  [403489] = { "兜にEndless Rageのルーンを刻みます：\r\n\n$I1\r\n与えるすべてのダメージから得る怒りが$N1%増加します。", nil, 0xf9c56804, nil, "um" },
  [403511] = { "Drain Life、Drain Soul、Wrackで吸収する体力または与えるダメージを$N1%増加させます。", nil, 0x2d5a7a50, nil, "um" },
  [403619] = { "術者を邪悪なエネルギーで包み、呪文のダメージと回復量を$N1増加させ、さらに精神の$N2%に等しい呪文のダメージと回復量を追加で得ます。加えて、5秒ごとに最大体力の$N3%を回復します。ウォーロックに同時にかけられるアーマー系呪文は1種類だけです。$D2持続します。", "呪文ダメージと治療量が$N1増加します。さらに$N3秒ごとに最大体力の$N2%を回復します。", 0x5b3e8f7c, 0xd6ad9fb3, "uu" },
  [403629] = { "敵に混沌の炎の矢を放ち、$N1のChaosダメージを与えます。Chaos Boltは必ず命中し、抵抗されず、その知識によってすべてのFire呪文が吸収効果を貫通するようになります。自分より$N2レベル以上高いモンスターに使うと、Chaos Boltは高い確率で抵抗されます。", nil, 0x399a9457, nil, "um" },
  [403677] = { "毎秒、対象から術者へ体力を$N1移し替えます。効果時間は$D1です。", "毎秒体力を$N1吸い取り、術者に与えます。", 0x55392778, 0x73cfd31b, "uu" },
  [403685] = { "毎秒、対象から術者へ体力を$N1移し替えます。効果時間は$D1です。", "毎秒体力を$N1吸い取り、術者に与えます。", 0x55392778, 0x73cfd31b, "uu" },
  [403686] = { "毎秒、対象から術者へ体力を$N1移し替えます。効果時間は$D1です。", "毎秒体力を$N1吸い取り、術者に与えます。", 0x55392778, 0x73cfd31b, "uu" },
  [403687] = { "毎秒、対象から術者へ体力を$N1移し替えます。効果時間は$D1です。", "毎秒体力を$N1吸い取り、術者に与えます。", 0x55392778, 0x73cfd31b, "uu" },
  [403688] = { "毎秒、対象から術者へ体力を$N1移し替えます。効果時間は$D1です。", "毎秒体力を$N1吸い取り、術者に与えます。", 0x55392778, 0x73cfd31b, "uu" },
  [403689] = { "毎秒、対象から術者へ体力を$N1移し替えます。効果時間は$D1です。", "毎秒体力を$N1吸い取り、術者に与えます。", 0x55392778, 0x73cfd31b, "uu" },
  [403789] = { "悪魔に変身し、アーマーが$N1%、体力が$N2%増加し、クリティカルヒットを受ける確率が$N3%減少し、脅威が$N4%増加し、Life Tapで得るマナが$N5%増加しますが、与えるすべてのダメージが$N6%減少します。Metamorphosisは一部のアビリティの機能を変え、新しいアビリティを与えます：\r\n\nSearing Pain：即時詠唱になります。\r\n\nShadow Bolt：Shadow Cleaveになります。近くの敵を最大$N7体攻撃するShadowの近接攻撃ですが、クールダウンが$D1あります。\r\n\nFear：Menaceに置き換わります。\r\n\n$I1\r\n対象をTauntして自分を攻撃させますが、対象がすでに自分を攻撃している場合は効果がありません。\r\n\nDemon Charge\r\n\n$I2\r\n敵に突撃し、$D2の間スタンさせます。戦闘中は使用できません。\r\n\nDemonic Howl\r\n\n$I3\r\n$D3の間、近くのすべての敵に自分へ攻撃を集中させます。", "アーマーが$N1%、体力が$N2%増加し、クリティカルヒットを受ける確率が$N3%低下し、脅威が$N4%増加し、Life Tapで得るマナが$N5%増加し、与えるダメージが$N6%減少します。一部のアビリティが変化し、新しいアビリティをいくつか得ます。", 0x0c431bda, 0x184055a6, "uu" },
  [403828] = { "対象を挑発して自分を攻撃させますが、対象がすでに自分を攻撃している場合は効果がありません。", "挑発されています。", 0x71de38fd, 0x36f56123, "uu" },
  [403835] = { { "近くの敵最大$N1体をShadowの鞭で打ち、それぞれに$N2を与えます。\r\n\nShadow Cleaveは、Shadow Boltが恩恵を受けるほとんどのタレントと効果の恩恵を受け、それらを発動させます。\r\n\nShadow Cleaveで対象に命中すると、Defenseスキルが$N4を超えるポイントごとにSpell Damageを$N3得ます。$D1持続します。", "近くの敵最大$N1体をShadowの鞭で打ち、それぞれに$N2を与えます。\r\n\nShadow Cleaveは、Shadow Boltが恩恵を受けるほとんどのタレントと効果の恩恵を受け、それらを発動させます。", shape = { "5/1", "2/0" } }, nil, 0x436ebc47, nil, "um" },
